// Fabrique une charge utile identique à celle de l'Error Trigger, pour tester le bloc à la main.
return [{ json: {
  execution: {
    id: '0',
    url: '',
    retryOf: null,
    error: { message: 'Échec simulé — test manuel du bloc WF1', stack: '' },
    lastNodeExecuted: 'Nœud de test',
    mode: 'manual',
  },
  workflow: { id: 'test', name: 'ZZ test erreur (simulé)' },
} }];

// MODE          : 'simulation' = tout est calculé, RIEN n'est envoyé sur Slack.
//                 'reel'       = les messages partent. Bascule sur décision explicite, après la recette.
// CANAL_ALERTE  : identifiant du canal Slack (C…), jamais son nom.
// FENETRE_DEDUP_HEURES : une erreur identique (workflow + nœud + message) n'est traitée qu'une fois par fenêtre.
// URL_INSTANCE  : base des liens « voir l'exécution » — vide = on prend execution.url fourni par n8n.
// REPARATION_AUTO : true  = l'incident part dans la file du réparateur local ; Slack n'est prévenu par n8n
//                           QUE si le réparateur n'a rien conclu après DELAI_FILET_MINUTES (poste éteint…).
//                   false = pas de réparateur (instance client) : alerte Slack immédiate.
// TABLE_INCIDENTS : id de la table de données « Incidents n8n » (file partagée avec le réparateur).
const reglages = {
  MODE: 'reel',
  CANAL_ALERTE: 'C0C27914SAZ',
  FENETRE_DEDUP_HEURES: 1,
  URL_INSTANCE: 'https://n8n-jtbx.srv1974245.hstgr.cloud',
  REPARATION_AUTO: true,
  DELAI_FILET_MINUTES: 30,
  TABLE_INCIDENTS: 'G6tieWFLeta7OEL5',
};
return $input.all().map(item => ({ json: { ...item.json, reglages } }));

// Met en forme l'incident et calcule la clé de dédoublonnage.
// Deux formes de charge utile : échec d'un nœud (execution.*) ou échec du déclencheur (trigger.*).
const NL = String.fromCharCode(10);
const entree = $input.first().json;
const r = entree.reglages;
const wf = entree.workflow || {};
const ex = entree.execution || {};
const tr = entree.trigger || {};
const err = ex.error || tr.error || {};
const noeud = ex.lastNodeExecuted || (err.node && err.node.name) || (ex.id ? 'inconnu' : 'déclencheur');
const message = String(err.message || err.description || 'erreur sans message').slice(0, 800);

let lien = ex.url || '';
if (r.URL_INSTANCE && wf.id && ex.id) {
  lien = r.URL_INSTANCE.replace(/\/+$/, '') + '/workflow/' + wf.id + '/executions/' + ex.id;
}

const fenetreMs = Math.max(1, Number(r.FENETRE_DEDUP_HEURES) || 1) * 3600 * 1000;
const tranche = Math.floor(Date.now() / fenetreMs);
const cle = [wf.id || wf.name || '?', noeud, message.slice(0, 160), tranche].join('|');

const quand = $now.setZone('Europe/Paris').toFormat("dd/MM/yyyy 'à' HH:mm");
const lignes = [
  ':rotating_light: *Échec d’un workflow n8n*',
  '*Workflow :* ' + (wf.name || 'inconnu') + (wf.id ? ' (`' + wf.id + '`)' : ''),
  '*Nœud en échec :* ' + noeud,
  '*Message :* ' + message,
  '*Quand :* ' + quand + (ex.mode ? ' — exécution ' + ex.mode : ''),
  lien ? '*Exécution :* <' + lien + '|ouvrir dans n8n>' : '*Exécution :* ' + (ex.id || '—'),
];
if (ex.retryOf) {
  lignes.push('_Nouvelle tentative de l’exécution ' + ex.retryOf + '._');
}

return [{ json: {
  executionId: ex.id ? String(ex.id) : '',
  workflowId: wf.id || '',
  workflowNom: wf.name || '',
  noeud,
  message,
  texte: lignes.join(NL),
  cle,
  statut: 'nouveau',
} }];

// Le réparateur n'a rien conclu dans le délai : n8n prévient lui-même, avec la situation.
const NL = String.fromCharCode(10);
const r = $('Réglages · Gestion des erreurs').first().json.reglages;
const ligne = $input.first().json;
const incident = $('Incidents – enregistrement').first().json;
const etat = ligne.statut === 'rapport_non_publie'
  ? 'le réparateur a conclu (' + (ligne.resume || '—') + ') mais n’a pas pu publier son compte rendu'
  : ligne.statut === 'en_cours'
    ? 'le réparateur a pris l’incident mais n’a pas conclu'
    : 'le réparateur ne l’a pas pris en charge (poste éteint ou réparateur arrêté ?)';
const texte = (ligne.texte || incident.texte) + NL +
  ':warning: *Pas de réparation automatique au bout de ' + r.DELAI_FILET_MINUTES + ' min* : ' + etat +
  '. À regarder à la main — sinon il le reprendra à son prochain démarrage et publiera son compte rendu ici.';
return [{ json: { texte, mode: r.MODE } }];

// Pas de réparateur sur cette instance : l'alerte part tout de suite.
const r = $('Réglages · Gestion des erreurs').first().json.reglages;
return $input.all().map(i => ({ json: { texte: i.json.texte, mode: r.MODE } }));

// MODE_GARDIEN      : 'simulation' = tout est calculé et la table est tenue à jour, RIEN n'est envoyé sur Slack.
