  MODE_GARDIEN: 'reel',
  URL_SIGNAL_VIE: 'https://hc-ping.com/c3b25148-a2e3-45a0-83bb-39697935f3ea',
  TABLE_SURVEILLES: '7QgsElRqld0DYeOz',
  ID_GESTION_ERREURS: 'GestErreursInst1',
  CANAL_ALERTE: 'C0C27914SAZ',
  HEURES_OUVREES: { jours: [1, 2, 3, 4, 5], debut: 8, fin: 18 },
  RAPPEL_HEURES: 24,
  URL_INSTANCE: 'https://n8n-jtbx.srv1974245.hstgr.cloud',
};
return [{ json: { reglages } }];

// Ne garde que les lignes actives et bien formées. Table vide : rien à contrôler, le bloc s'arrête là.
return $input.all()
  .filter(i => i.json.workflowId && i.json.actif !== false)
  .map(i => ({ json: i.json }));

// Pour chaque workflow : anomalie constatée, puis décision (alerte, rappel, rétabli ou rien).
