function heuresOuvrees(debut, fin) {
  const p = r.HEURES_OUVREES;
  let total = 0;
  let jour = debut.startOf('day');
  let garde = 0;
  while (jour <= fin && garde < 400) {
    if (p.jours.includes(jour.weekday)) {
      const a = jour.set({ hour: p.debut }), b = jour.set({ hour: p.fin });
      const s = debut > a ? debut : a, e = fin < b ? fin : b;
      if (e > s) total += e.diff(s, 'minutes').minutes;
    }
    jour = jour.plus({ days: 1 });
    garde++;
  }
  return total / 60;
}

