  const rattache = (wf.settings || {}).errorWorkflow || '';
  if (rattache !== r.ID_GESTION_ERREURS) {
    return { code: 'detache', constat: 'ses échecs ne sont plus ni signalés ni réparés (Error workflow : ' + (rattache || 'vide') + ').' };
  }
  const max = Number(ligne.silence_max_h);
  if (!max || max <= 0) return { code: 'ok' };
  if (exec.statusCode !== 200) return { code: 'lecture_impossible', constat: 'le gardien n’arrive pas à lire les exécutions de ce workflow (HTTP ' + exec.statusCode + ').' };
  const derniere = ((exec.body || {}).data || [])[0];
  const repere = derniere ? (derniere.startedAt || derniere.createdAt) : ligne.createdAt;
  const depuis = DateTime.fromISO(repere).setZone('Europe/Paris');
  const ouvrees = ligne.plage === 'ouvrees';
  const ecoule = ouvrees ? heuresOuvrees(depuis, maintenant) : maintenant.diff(depuis, 'hours').hours;
  if (ecoule <= max) return { code: 'ok' };
  return { code: 'silence', constat: 'aucune exécution depuis ' + duree(ecoule) + (ouvrees ? ' d’heures ouvrées' : '') +
    ' (maximum prévu : ' + max + ' h). ' + (derniere ? 'Dernière exécution le ' + date(repere) + '.' : 'Aucune exécution connue.') };
}

const LIBELLES = {
  introuvable: ['Workflow introuvable', 'vérifier s’il a été supprimé ou réimporté sous un autre identifiant, puis corriger ou désactiver sa ligne dans la table « Workflows surveillés ».'],
  lecture_impossible: ['Gardien aveugle', 'vérifier la clé d’API « Gardien » (Settings → n8n API) et l’identifiant « API n8n – Gardien ».'],
  depublie: ['Workflow dépublié', 'l’ouvrir, recharger la page (F5), puis Publier.'],
  detache: ['Workflow détaché de « Gestion des erreurs »', 'dans ses réglages, Error workflow → « Gestion des erreurs », puis enregistrer et publier.'],
  silence: ['Panne silencieuse', 'vérifier que le workflow est publié, que ses déclencheurs sont actifs et à la bonne heure.'],
};

const sortie = [];
lignes.forEach((l, i) => {
  const ligne = l.json;
  const d = diagnostiquer(ligne, (etats[i] || {}).json || {}, (execs[i] || {}).json || {});
  const avant = ligne.etat || 'ok';
  const lien = base + '/workflow/' + ligne.workflowId;
  const nom = ligne.nom || ligne.workflowId;
  let action = null;
  let depuis = ligne.depuis || '';
  let derniere = ligne.derniere_alerte || '';
  if (d.code === 'ok' && avant !== 'ok') {
    action = 'retabli';
  } else if (d.code !== 'ok' && d.code !== avant) {
    action = 'alerte';
    depuis = maintenant.toISO();
  } else if (d.code !== 'ok' && (!derniere || maintenant.diff(DateTime.fromISO(derniere), 'hours').hours >= r.RAPPEL_HEURES)) {
    action = 'rappel';
  }
  if (!action) return;

  let texte;
  if (action === 'retabli') {
    const ancien = (LIBELLES[avant] || [avant])[0];
    texte = ':white_check_mark: *Rétabli — ' + nom + '* — fin de « ' + ancien + ' »' + (ligne.depuis ? ' (depuis le ' + date(ligne.depuis) + ')' : '') + '.';
    depuis = '';
    derniere = '';
  } else {
    const [titre, aFaire] = LIBELLES[d.code];
    const entete = action === 'rappel'
      ? ':repeat: *Toujours en cours — ' + titre + ' — ' + nom + '* (depuis le ' + date(depuis) + ')'
      : ':large_orange_circle: *' + titre + ' — ' + nom + '*';
    texte = [entete, '*Constat :* ' + d.constat, '*À faire :* ' + aFaire, '*Workflow :* <' + lien + '|ouvrir dans n8n>'].join(NL);
    derniere = maintenant.toISO();
  }
  sortie.push({ json: { id: ligne.id, workflowId: ligne.workflowId, action, etat: d.code, depuis, derniere_alerte: derniere, texte } });
});
return sortie;

// Workflows publiés, rattachés à « Gestion des erreurs », mais absents de « Workflows surveillés ».
// Une ligne présente, même avec actif décoché, compte comme inscrite (c'est la façon de dire « ne pas surveiller »).
// Les workflows en ZZ (tests) sont ignorés. Clé = workflow + tranche de RAPPEL_HEURES : un rappel par tranche au plus.
const NL = String.fromCharCode(10);
const r = $('Réglages · Gardien').first().json.reglages;
const reponse = $input.first().json;
if (reponse.statusCode !== 200) return [];
const inscrits = new Set($('Table – workflows surveillés').all().map(i => i.json.workflowId).filter(Boolean));
const tranche = Math.floor(Date.now() / (r.RAPPEL_HEURES * 3600 * 1000));
const base = r.URL_INSTANCE.replace(/[/]+$/, '');
return ((reponse.body || {}).data || [])
  .filter(w => (w.settings || {}).errorWorkflow === r.ID_GESTION_ERREURS && !inscrits.has(w.id) && !/^ZZ/i.test(w.name || ''))
  .map(w => ({ json: {
    workflowId: w.id,
    cle: w.id + '|' + tranche,
    texte: [
      ':large_blue_circle: *Workflow non surveillé — ' + w.name + '*',
      '*Constat :* rattaché à « Gestion des erreurs » mais absent de la table « Workflows surveillés » : ses pannes silencieuses (dépublié, muet…) ne seraient pas détectées.',
      '*À faire :* ajouter sa ligne dans « Workflows surveillés » — ou demander à Claude « surveille ' + w.name + ' ». Pour ne pas le surveiller : une ligne avec `actif` décoché.',
      '*Workflow :* <' + base + '/workflow/' + w.id + '|ouvrir dans n8n>',
    ].join(NL),
  } }));
